from taf.transport.ssh import ssh
import requests
import logging

log = logging.getLogger(__name__)


class SocatSession:
    def __init__(self):
        self.ssh = ssh()

    def start_socat(self, socat_port, connection, fsm_ip, fsm_port):
        """
        We have to prevent socat's ssh channel from being collected,
        otherwise next command sent via this ssh client will make ssh server
        kill socat (because of get_pty=True in ssh.send_command).
        self._socat_channel stores the channel and prevents it from happening.

        :param socat_port: Port, onto which socat can listen for requests.
        :param connection: Alias of ssh connection, which can be created by
        connect_to method from taf.transport.ssh library.
        :param fsm_ip: IP address assigned to fsm interface, from which
        a connection with OAM can be established.
        :param fsm_port: Port on fsm onto which requests will be passed.
        :return:
        """
        command = 'socat -v TCP-LISTEN:{},fork,reuseaddr TCP:{}:{}'.format(
            socat_port, fsm_ip, fsm_port)
        self.ssh.send_command(command=command, get_pty=True,
                              connection=connection)
        ssh_client = self.ssh.get_connection_by_alias(connection)
        self._socat_channel = ssh_client.last_stdout.channel

    @staticmethod
    def check_connection(url, socat_port):
        """
        The purpose of this method is to send some basic request- it will tell
        us if socat is ready to listen for requests on specified socat_port.

        :param url: Http url, for example: http://10.1.1.1
        :param socat_port: Port, onto which socat is listening for requests.
        :return: True if connection is established, False otherwise.
        """
        endpoint = '/mz/p/v1/pbts/1/fsm/1/detectedHw'
        request_url = '{}:{}{}'.format(url, socat_port, endpoint)
        connection = True
        try:
            requests.get(request_url)
        except requests.exceptions.ConnectionError as e:
            log.info(e)
            connection = False
        return connection
